// Reimplementation of the bech32 library's convertbits function.
// Converts a byte array from one bit width to another, regrouping bits
// with optional zero-padding of the final partial group.

/**
 * Convert a list of integers from `frombits`-wide groups to `tobits`-wide groups.
 * Mirrors Python bech32.convertbits(data, frombits, tobits, pad=True).
 *
 * @param {number[]} data
 * @param {number} frombits
 * @param {number} tobits
 * @param {boolean} [pad=true]
 * @returns {number[]|null} the converted list, or null if an input value
 *          is out of range or (when pad=false) bits are left over.
 */
export function convertbits(data, frombits, tobits, pad = true) {
  let acc = 0;
  let bits = 0;
  const ret = [];
  const maxv = (1 << tobits) - 1;
  const maxAcc = (1 << (frombits + tobits - 1)) - 1;
  for (const value of data) {
    if (value < 0 || value >> frombits) {
      return null;
    }
    acc = ((acc << frombits) | value) & maxAcc;
    bits += frombits;
    while (bits >= tobits) {
      bits -= tobits;
      ret.push((acc >> bits) & maxv);
    }
  }
  if (pad) {
    if (bits) {
      ret.push((acc << (tobits - bits)) & maxv);
    }
  } else if (bits >= frombits || ((acc << (tobits - bits)) & maxv)) {
    return null;
  }
  return ret;
}

// Helpers for parsing integers the way Python's int(str) does.

/**
 * Parse a string like Python's int(): optional surrounding whitespace,
 * optional sign, decimal digits only. Throws on anything else.
 *
 * @param {string} s
 * @returns {number}
 */
export function pyInt(s) {
  const trimmed = String(s).trim();
  if (!/^[+-]?\d+$/.test(trimmed)) {
    throw new Error(`invalid literal for int() with base 10: '${s}'`);
  }
  return parseInt(trimmed, 10);
}

// Minimal re-implementation of the argparse behavior used by the original
// script: required options --a (str), --b/--c/--d (int), supporting both
// "--opt value" and "--opt=value" forms, with argparse-style errors.

import { pyInt } from './pyint.mjs';

const OPTIONS = ['a', 'b', 'c', 'd'];
const INT_OPTIONS = new Set(['b', 'c', 'd']);

function usage(prog) {
  return `usage: ${prog} [-h] --a A --b B --c C --d D`;
}

function fail(prog, message) {
  console.error(usage(prog));
  console.error(`${prog}: error: ${message}`);
  process.exit(2);
}

/**
 * Parse argv (already sliced to the user arguments) like the Python
 * argparse setup in test14.py. Exits with code 2 on any parsing error,
 * matching argparse.
 *
 * @param {string} prog program name used in usage/error messages
 * @param {string[]} argv user-supplied arguments
 * @returns {{a: string, b: number, c: number, d: number}}
 */
export function parseArgs(prog, argv) {
  const values = {};
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    if (token === '-h' || token === '--help') {
      console.log(usage(prog));
      process.exit(0);
    }
    const match = /^--([a-z]+)(?:=(.*))?$/.exec(token);
    if (match && OPTIONS.includes(match[1])) {
      const name = match[1];
      let value = match[2];
      if (value === undefined) {
        i += 1;
        if (i >= argv.length) {
          fail(prog, `argument --${name}: expected one argument`);
        }
        value = argv[i];
      }
      if (INT_OPTIONS.has(name)) {
        try {
          values[name] = pyInt(value);
        } catch {
          fail(prog, `argument --${name}: invalid int value: '${value}'`);
        }
      } else {
        values[name] = value;
      }
    } else {
      extras.push(token);
    }
  }

  if (extras.length > 0) {
    fail(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  const missing = OPTIONS.filter((name) => values[name] === undefined);
  if (missing.length > 0) {
    fail(
      prog,
      `the following arguments are required: ${missing
        .map((name) => `--${name}`)
        .join(', ')}`
    );
  }

  return values;
}

// Formatting helpers that reproduce Python's print() output exactly.

/**
 * Format an array of numbers the way Python's print() renders a list of
 * ints: "[1, 2, 3]".
 *
 * @param {number[]} list
 * @returns {string}
 */
export function pyListRepr(list) {
  return `[${list.join(', ')}]`;
}

// Node.js (ESM) port of /workspace/dataset/bech32/test14.py.
// Converts comma-separated integers from --b bits to --c bits, then from
// --c bits to --d bits, printing both intermediate results exactly as
// Python's print() does.

import { basename } from 'node:path';
import { fileURLToPath } from 'node:url';
import { convertbits } from './lib/convertbits.mjs';
import { parseArgs } from './lib/argparser.mjs';
import { pyInt } from './lib/pyint.mjs';
import { pyListRepr } from './lib/pyformat.mjs';

function main() {
  const prog = basename(fileURLToPath(import.meta.url));
  const args = parseArgs(prog, process.argv.slice(2));

  const data = args.a.split(',').map(pyInt);

  const step1 = convertbits(data, args.b, args.c); // to intermediate bits
  if (step1 === null) {
    // Python: convertbits returned None, the next call raises TypeError.
    console.error(
      "TypeError: 'NoneType' object is not iterable"
    );
    process.exit(1);
  }
  const step2 = convertbits(step1, args.c, args.d); // to final bits

  console.log(pyListRepr(step1));
  console.log(pyListRepr(step2));
}

main();
